// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(address caller) internal {
        bool reverted;
        caller = address(this);
        try c.setL1BlockValues(
            uint64(1), uint64(2), uint256(3), bytes32(0), uint64(5), bytes32(0), uint256(7), uint256(8)
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (address(this) != c.depositorAccount()));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
